<?php defined('BASEPATH') or exit('No direct script access allowed');$company_page_title='Calendário da empresa';require __DIR__.'/layout_head.php';$ce=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$values=$calendar['preferences'];$definitions=CompanyCalendarSources::definitions();$weekdays=['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'];$grouped=[];foreach($calendar['events']as$event)$grouped[$event['date']][]=$event;$url=CompanyRequestScope::adminUrl($this,'company_calendar');$navigation=static function($anchor)use($calendar,$calendar_view,$url){$q=['anchor'=>$anchor,'view'=>$calendar_view,'title'=>$calendar['filters']['title'],'client_id'=>$calendar['filters']['client_id']??'','sources_present'=>'1','sources'=>$calendar['filters']['sources']];return$url.'?'.http_build_query($q);};?>
<style>.company-calendar-grid{width:100%;table-layout:fixed;border-collapse:collapse}.company-calendar-grid th,.company-calendar-grid td{border:1px solid #cbd5e1;padding:8px;vertical-align:top}.company-calendar-grid td{height:110px}.company-calendar-event{display:block;border-left:5px solid;padding:4px 7px;margin:5px 0;background:#f8fafc;overflow-wrap:anywhere}.company-calendar-event a{color:#0f172a}.company-calendar-tools{display:flex;gap:12px;flex-wrap:wrap;align-items:end;margin:16px 0}.company-calendar-day-label{font-weight:bold}.company-calendar-settings{margin-top:24px}.company-calendar-overflow{font-size:12px;color:#475569}.company-calendar-scroll{overflow:auto}@media(max-width:767px){.company-calendar-grid{min-width:750px}}</style>
<section class="company-settings-card" data-company-calendar="<?= (int)$issuer; ?>"><h1>Calendário da empresa</h1><p>Vencimentos dos registros privados que você pode consultar nesta empresa. Todas as entradas representam datas inteiras. Eventos pessoais, departamentos, lembretes e Google não são usados.</p>
<form method="get" action="<?= $ce($url); ?>" class="company-calendar-tools" id="company-calendar-filter"><label>Data de referência<input type="date" name="anchor" value="<?= $ce($calendar_anchor); ?>" required></label><label>Visualização<select name="view" id="company-calendar-view"><?php foreach(CompanyCalendarPresentation::views()as$key=>$label){?><option value="<?= $ce($key); ?>" <?= $key===$calendar_view?'selected':''; ?>><?= $ce($label); ?></option><?php }?></select></label><label>Trecho do título<input name="title" maxlength="191" value="<?= $ce($calendar['filters']['title']); ?>"></label><?php if($can_filter_clients){?><label>ID do cliente autorizado<input name="client_id" inputmode="numeric" pattern="[1-9][0-9]*" value="<?= $ce($calendar['filters']['client_id']??''); ?>"></label><?php }?><input type="hidden" name="sources_present" value="1"><fieldset><legend class="tw-text-sm">Fontes habilitadas e autorizadas</legend><?php foreach($calendar['available_sources']as$source){?><label><input type="checkbox" name="sources[]" value="<?= $ce($source); ?>" <?= in_array($source,$calendar['filters']['sources'],true)?'checked':''; ?>> <?= $ce($definitions[$source]['label']); ?></label> <?php }?></fieldset><button type="submit" class="btn btn-primary">Aplicar filtros</button></form>
<nav aria-label="Navegação do calendário"><a href="<?= $ce($navigation($calendar_range['previous'])); ?>">Anterior</a> · <a href="<?= $ce($navigation(gmdate('Y-m-d'))); ?>">Hoje</a> · <a href="<?= $ce($navigation($calendar_range['next'])); ?>">Próximo</a></nav><p role="status" data-calendar-total="<?= (int)$calendar['total']; ?>"><?= (int)$calendar['total']; ?> entradas autorizadas no intervalo <?= $ce($calendar_range['start']); ?> a <?= $ce($calendar_range['end']); ?>.</p>
<?php if(in_array($calendar_view,['dayGridMonth','dayGridWeek'],true)){?><div class="company-calendar-scroll"><table class="company-calendar-grid" data-calendar-first-day="<?= (int)$values['calendar_first_day']; ?>"><thead><tr><?php for($w=0;$w<7;$w++){?><th scope="col"><?= $ce($weekdays[((int)$values['calendar_first_day']+$w)%7]); ?></th><?php }?></tr></thead><tbody><?php $day=new DateTimeImmutable($calendar_range['start']);$end=new DateTimeImmutable($calendar_range['end']);$index=0;while($day<=$end){if($index%7===0)echo'<tr>';$key=$day->format('Y-m-d');$events=$grouped[$key]??[];?><td data-calendar-date="<?= $ce($key); ?>"><div class="company-calendar-day-label"><?= $ce($day->format('d/m')); ?></div><?php foreach(array_slice($events,0,(int)$values['calendar_events_limit'])as$event){?><article class="company-calendar-event" data-calendar-event="<?= $ce($event['id']); ?>" style="border-left-color:<?= $ce($event['color']); ?>"><a href="<?= $ce(CompanyRequestScope::adminUrl($this,$event['path'])); ?>"><?= $ce($event['title']); ?></a><small> · <?= $ce($definitions[$event['source']]['label']); ?></small></article><?php }if(count($events)>(int)$values['calendar_events_limit']){?><p class="company-calendar-overflow">+<?= count($events)-(int)$values['calendar_events_limit']; ?> neste dia. Selecione a visualização Dia para consultar todas.</p><?php }?></td><?php $index++;if($index%7===0)echo'</tr>';$day=$day->modify('+1 day');}?></tbody></table></div>
<?php }else{foreach(new DatePeriod(new DateTimeImmutable($calendar_range['start']),new DateInterval('P1D'),(new DateTimeImmutable($calendar_range['end']))->modify('+1 day'))as$day){$key=$day->format('Y-m-d');?><section data-calendar-date="<?= $ce($key); ?>"><h2 class="tw-text-lg"><?= $ce($weekdays[(int)$day->format('w')].' '.$day->format('d/m/Y')); ?></h2><?php if(empty($grouped[$key])){?><p>Sem entradas autorizadas.</p><?php }foreach($grouped[$key]??[]as$event){?><article class="company-calendar-event" data-calendar-event="<?= $ce($event['id']); ?>" style="border-left-color:<?= $ce($event['color']); ?>"><span>Dia inteiro · </span><a href="<?= $ce(CompanyRequestScope::adminUrl($this,$event['path'])); ?>"><?= $ce($event['title']); ?></a><small> · <?= $ce($definitions[$event['source']]['label']); ?></small></article><?php }?></section><?php }}?>
<?php if($can_configure){?><details class="company-calendar-settings" id="company-calendar-settings"><summary>Configurar este calendário</summary><p>Preferências próprias desta empresa, inclusive na principal. Habilitar uma fonte não concede permissão para consultar seus registros. O limite vale para as grades de mês e semana.</p><?= form_open($url,['id'=>'company-calendar-settings-form']); ?><input type="hidden" name="company_calendar_csrf" value="<?= $ce($calendar_csrf); ?>"><input type="hidden" name="revision" value="<?= (int)$calendar['revision']; ?>"><label>Limite de entradas por dia nas grades<input name="settings[calendar_events_limit]" type="number" min="1" max="50" required value="<?= $ce($values['calendar_events_limit']); ?>"></label><label>Visualização inicial<select name="settings[default_view_calendar]"><?php foreach(CompanyCalendarPresentation::views()as$key=>$label){?><option value="<?= $ce($key); ?>" <?= $values['default_view_calendar']===$key?'selected':''; ?>><?= $ce($label); ?></option><?php }?></select></label><label>Primeiro dia da semana<select name="settings[calendar_first_day]"><?php foreach($weekdays as$key=>$label){?><option value="<?= $key; ?>" <?= $values['calendar_first_day']===(string)$key?'selected':''; ?>><?= $ce($label); ?></option><?php }?></select></label><label>Mostrar apenas tarefas atribuídas a quem consulta<select name="settings[calendar_only_assigned_tasks]"><option value="1" <?= $values['calendar_only_assigned_tasks']==='1'?'selected':''; ?>>Sim</option><option value="0" <?= $values['calendar_only_assigned_tasks']==='0'?'selected':''; ?>>Não, dentro das permissões originais</option></select></label><div class="company-settings-grid"><?php foreach(['invoices'=>'Faturas','estimates'=>'Orçamentos','proposals'=>'Propostas','projects'=>'Projetos','tasks'=>'Tarefas de projeto e avulsas','contracts'=>'Contratos']as$kind=>$label){$toggle='show_'.$kind.'_on_calendar';$color=match($kind){'invoices'=>'calendar_invoice_color','estimates'=>'calendar_estimate_color','proposals'=>'calendar_proposal_color','projects'=>'calendar_project_color','tasks'=>'calendar_task_color','contracts'=>'calendar_contract_color'};?><fieldset><legend><?= $ce($label); ?></legend><label>Fonte<select name="settings[<?= $ce($toggle); ?>]"><option value="0" <?= $values[$toggle]==='0'?'selected':''; ?>>Desabilitada</option><option value="1" <?= $values[$toggle]==='1'?'selected':''; ?>>Habilitada com ACL original</option></select></label><label>Cor<input type="color" name="settings[<?= $ce($color); ?>]" value="<?= $ce($values[$color]); ?>" required></label></fieldset><?php }?></div><button type="submit" class="btn btn-default">Salvar preferências desta empresa</button><?= form_close(); ?></details><?php }?></section>
